// Prose-documentation search for RoleCall (Wave 1 additive feature).
//
// Backs BOTH `rolecall docs search <query>` (src/cli/commands/docs.ts) and the
// clientless agent tool `docs.search` over GET /mcp/docs
// (src/orchestrator/routes.ts). One implementation, two consumers — never drift.
//
// Documents are sourced from the bundled EMBEDDED_DOCS map (generated by
// scripts/embed-docs.ts) so search works with NO docs/ folder present — required
// for the standalone `bun build --compile` binary. A dev-mode disk fallback
// (resolving docs/content relative to THIS module) is kept only behind an
// empty-map check, so it is never hit on the normal path.

import { readdirSync, statSync } from "node:fs";
import { readFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { dirname, join, relative } from "node:path";

// Bundled doc corpus generated by scripts/embed-docs.ts. Importing it makes the
// compiled binary self-contained; see loadDocuments() for the dev-mode fallback.
import { EMBEDDED_DOCS } from "./embedded-content";

/** Default number of hits returned by {@link searchDocs}. */
export const DEFAULT_DOC_SEARCH_LIMIT = 20;

/** Hard ceiling on how many hits a single search may return. */
export const MAX_DOC_SEARCH_LIMIT = 100;

/** A single documentation hit: which doc section matched and surrounding text. */
export interface DocHit {
  /** Path relative to docs/content, e.g. `concepts/templating.md`. */
  file: string;
  /** Nearest preceding markdown heading, or "(no heading)" when none precedes. */
  heading: string;
  /** 1-based line number of the matched line within its file. */
  line: number;
  /** The matched source line, trimmed. */
  snippet: string;
}

/** Result envelope returned by {@link searchDocs}. */
export interface DocSearchResult {
  /** The (trimmed, lowercased-for-match) query term echoed back. */
  query: string;
  /** Number of hits actually returned (after grouping/sorting/limiting). */
  count: number;
  /** Ordered hits; see {@link searchDocs} for the ordering contract. */
  hits: DocHit[];
}

interface SearchOptions {
  /** Max hits to return (default 20, clamped to 100). */
  limit?: number;
}

const HEADING_RE = /^#{1,6}\s+/;

// Resolve the docs/content tree relative to THIS module: ../.. back out of
// src/docs to the project root, then into docs/content. Kept as an explicit
// join (rather than a bare ../../docs/content specifier) so it cannot resolve
// one level too low and accidentally read sibling files outside content/.
const HERE = dirname(fileURLToPath(import.meta.url));
const CONTENT_ROOT = join(HERE, "..", "..", "docs", "content");

/** Recursively gather *.md files under root, returning paths relative to the content root. */
function collectMarkdownFiles(root: string): string[] {
  const out: string[] = [];
  for (const entry of readdirSync(root)) {
    const full = join(root, entry);
    if (statSync(full).isDirectory()) out.push(...collectMarkdownFiles(full));
    else if (entry.endsWith(".md")) out.push(relative(CONTENT_ROOT, full));
  }
  return out.sort();
}

/**
 * Source of truth for search docs. Returns the bundled {@link EMBEDDED_DOCS}
 * map first (self-contained; works inside the standalone binary). If that map is
 * somehow empty — e.g. a dev checkout where `scripts/embed-docs.ts` never ran —
 * fall back to walking docs/content from disk relative to THIS module. The disk
 * walk lives ONLY behind the empty-check so it is never hit on the normal path.
 */
async function loadDocuments(): Promise<Map<string, string[]>> {
  if (Object.keys(EMBEDDED_DOCS).length > 0) {
    return new Map(Object.entries(EMBEDDED_DOCS));
  }

  // Dev-mode fallback: resolve docs/content relative to THIS module (../.. back
  // out of src/docs to the project root, then into docs/content). Kept as an
  // explicit join so it cannot resolve one level too low and read sibling files.
  const docs = new Map<string, string[]>();
  for (const rel of collectMarkdownFiles(CONTENT_ROOT)) {
    const text = await readFile(join(CONTENT_ROOT, rel), "utf8");
    docs.set(rel, text.split(/\r?\n/));
  }
  return docs;
}

/**
 * Case-insensitive substring search across every prose-doc markdown file.
 *
 * Contract: scans each file top-to-bottom, tracking the nearest PRECEDING
 * markdown heading (a line starting with up to six `#`) for every matching line.
 * Hits are grouped per file, ordered primarily by their file's match-count
 * descending then by line ascending, flattened, and finally truncated to the
 * requested `limit` (default {@link DEFAULT_DOC_SEARCH_LIMIT}, hard-capped at
 * {@link MAX_DOC_SEARCH_LIMIT}).
 *
 * @param query Term to find (case-insensitive substring); whitespace-trimmed, must be non-empty.
 * @param opts Optional limit override.
 * @returns Query echo + ordered hits. Throws if the query is empty after trimming.
 */
export async function searchDocs(query: string, opts?: SearchOptions): Promise<DocSearchResult> {
  const q = String(query ?? "").trim();
  if (q.length === 0) {
    throw new Error("searchDocs requires a non-empty query");
  }
  const qLower = q.toLowerCase();

  const limitRaw = opts?.limit ?? DEFAULT_DOC_SEARCH_LIMIT;
  const limit = Math.min(Math.max(1, Math.floor(limitRaw)), MAX_DOC_SEARCH_LIMIT);

  const docs = await loadDocuments();
  // Per-file accumulators keyed by relative path; preserves insertion order.
  const perFileHits = new Map<string, DocHit[]>();

  for (const [relPath, lines] of docs) {
    let lastHeading = "(no heading)";
    lines.forEach((line, i) => {
      if (HEADING_RE.test(line)) {
        lastHeading = line.trim();
        return;
      }
      if (!line.toLowerCase().includes(qLower)) return;
      const hit: DocHit = { file: relPath, heading: lastHeading, line: i + 1, snippet: line.trim() };
      const existing = perFileHits.get(relPath);
      if (existing) existing.push(hit);
      else perFileHits.set(relPath, [hit]);
    });
  }

  // Tag each hit with its file's match-count via hits.length, then sort
  // files-by-count-desc then line-asc in a single stable pass before flattening.
  const flat: Array<{ hit: DocHit; fileCount: number }> = [];
  perFileHits.forEach((hits) => {
    const fileCount = hits.length;
    for (const hit of hits) flat.push({ hit, fileCount });
  });
  flat.sort((a, b) => {
    if (a.fileCount !== b.fileCount) return b.fileCount - a.fileCount;
    return a.hit.line - b.hit.line;
  });

  const hits = flat.slice(0, limit).map((entry) => entry.hit);
  return { query: q, count: hits.length, hits };
}
